const app=document.querySelector('#app'), dialog=document.querySelector('#dialog');
let state={events:[]},tasks=[],selected='',page='events',seen=new Set(),busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
