function isTrustedPage(value){try{let u=new URL(value),host=u.hostname.toLowerCase();return u.protocol==='https:'&&!u.username&&!u.password&&(host==='taobao.com'||host.endsWith('.taobao.com')||host==='tmall.com'||host.endsWith('.tmall.com'))&&!/(?:^|[?&#;])(?:access_?token|token|session|sessionkey|auth|password|cookie|sid|sign|code)=/i.test(u.search+u.hash)}catch{return false}}
