async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Invoice-Request':'local-app'},body:data===undefined?undefined:JSON.stringify(data)});let v=await r.json();if(!r.ok){const error=Error(v.error||'操作失败');error.status=r.status;throw error}return v}
async function save(){try{const result=await api('state','PUT',state);state.revision=result.revision;return result}catch(error){if(error.status===409){state=await api('state');if(dialog.open)dialog.close();render();error.message='订单数据已被另一个页面更新，已载入最新记录；请核对后再操作。'}throw error}}
function message(s){let n=document.createElement('div');n.className='toast';n.textContent=s;document.body.append(n);setTimeout(()=>n.remove(),4500)}
function modal(html){dialog.innerHTML=`<div class="modal">${html}</div>`;dialog.showModal();dialog.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close())}
function rawStatus(o){if(!o.invoice?.name&&!o.statusTags?.length&&!o.manualStatus&&['pending','submitted'].includes(o.execution))return '开票中';if(o.statusTags?.length)return o.statusTags.join(' · ');if(OrderSummary.hasChatImages(o))return '人工审查图片';if(o.manualStatus){if(['已开票 · PDF 已保存','已开票 · 图片已保存 · 需人工核对'].includes(o.manualStatus))return '已开票';return o.manualStatus}if(o.invoice?.name||o.images?.length)return '已开票';if(o.qr?.name)return '已收到二维码 · 待扫码';if(o.execution==='seller_contacted')return '已联系客服 · 等待人工审核';if(o.execution==='chat_checked')return '已查看客服 · 未发现可确认 PDF';if(o.execution==='not_applied')return '未申请 · 待处理';if(o.execution==='manual_required')return ['no_action','contact_seller'].includes(o.action)?'联系客服 · 需核对':'需人工核对';if(o.invoiceStatus==='issued'||o.execution==='issued')return '已开票 · 文件未保存';if(['pending','submitted'].includes(o.execution))return '开票中';if(o.execution==='downloaded'||o.execution==='file_exists')return '下载结果待核对';if(o.execution&&o.execution!=='skipped')return '需人工核对';if(['download_invoice','inspect_invoice'].includes(o.action))return '可查看或下载';if(o.action==='apply_invoice')return '有开票入口 · 待确认';if(['no_action','contact_seller'].includes(o.action))return '联系客服';return '需人工确认'}
function status(o){const value=rawStatus(o);return value==='已开票'&&!OrderSummary.hasInvoiceLink(o)?'发票未关联 · 待核对':value}
function rawStatusTags(o){if(!o.invoice?.name&&!o.statusTags?.length&&!o.manualStatus&&['pending','submitted'].includes(o.execution))return o.images?.length?['系统开票中','人工审查图片']:['系统开票中'];if(Array.isArray(o.statusTags)&&o.statusTags.length)return o.statusTags.slice(0,2);if(OrderSummary.hasChatImages(o))return ['人工审查图片'];const first=status(o);return (o.images?.length||o.invoice?.name&&OrderSummary.needsReview(o))&&!first.includes('人工')?[first,'需人工核对']:[first]}
function statusTags(o){const note=String(o.manualNote??o.reason??''),raw=rawStatusTags(o),mapped=raw.map(label=>{if(['已联系客服，客服开票','已联系客服，客服开票中'].includes(label))return '客服开票中';if(label==='已开票'&&!OrderSummary.hasInvoiceLink(o))return '待人工确认';if(label==='待确认，客服发了图片')return '待确认';if(['已开票','待人工确认','待确认','系统开票中','客服开票中','手动录入'].includes(label))return label;if(note.includes('已联系客服，开票中'))return '客服开票中';if(label==='开票中')return '系统开票中';return '待人工确认'});const result=[...new Set(mapped)].slice(0,2);if(o.manualAdded&&!result.includes('手动录入')){if(result.length>=2)result[1]='手动录入';else result.push('手动录入')}return result}
const ORDER_STATUS_OPTIONS=['已开票','待人工确认','待确认','系统开票中','客服开票中','手动录入'];
function statusOptions(value,optional=false){const choices=[...ORDER_STATUS_OPTIONS];if(value&&!choices.includes(value))choices.unshift(value);return `${optional?'<option value="">无第二标签</option>':''}${choices.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}`}
function statusClass(label){if(label==='手动录入')return 'status-manual-entry';if(label.includes('人工')||label==='待确认')return 'status-review';if(label==='已开票')return 'status-saved';if(label==='开票中'||label==='系统开票中')return 'status-pending';if(label==='客服开票中')return 'status-customer';return 'status-review'}
function shell(content){app.innerHTML=`<aside><div class="brand"><span>票</span><div><b>票夹</b><small>INVOICE WORKSPACE</small></div></div><div class="nav-label">工作空间</div><button data-nav="events" class="${page==='events'?'active':''}">▦　Event</button><button data-nav="orders" class="${page==='orders'?'active':''}">☷　订单工作台</button><button data-nav="tasks" class="${page==='tasks'?'active':''}">◷　任务记录</button><button data-nav="settings" class="${page==='settings'?'active':''}">⚙　开票资料</button><div class="side-foot">本机连接器<br><small>浏览器需在本机运行</small></div></aside><main><header><span>票夹 / ${page==='events'?'Event':page==='orders'?'订单工作台':page==='tasks'?'任务记录':'开票资料'}</span><span class="pill">● 本机模式</span></header><div class="content">${content}</div></main>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;render()})}
function render(){if(page==='events')return renderEvents();if(page==='tasks')return renderTasks();if(page==='settings')return renderSettings();return renderOrders()}
async function renderSettings(){try{const c=await api('config'),fields=[['companyName','发票抬头','必填'],['taxNo','纳税人识别号 / 税号','必填'],['email','接收邮箱',''],['phone','联系电话',''],['address','注册地址',''],['bankName','开户银行',''],['bankAccount','银行账号',''],['paperShippingName','纸质发票收件人',''],['paperShippingPhone','纸质发票联系电话',''],['paperShippingAddress','纸质发票收件地址','']];shell(`<div class="eyebrow">LOCAL INVOICE PROFILE</div><div class="title-row"><div><h1>开票资料</h1><p>保存到这台电脑，后续开票申请会使用这里填写的信息。</p></div></div><div class="notice">资料仅保存在本机的 engine 配置文件中，不会上传到 GitHub。提交开票前，仍请核对抬头和税号。</div><form id="invoice-profile" class="panel settings-form"><div class="settings-grid">${fields.map(([key,label,required])=>`<label>${label}${required?` <span class="required">${required}</span>`:''}<input name="${key}" value="${esc(c[key]||'')}" ${required?'required':''} ${key==='taxNo'?'autocomplete="off"':''}></label>`).join('')}</div><label>联系商家时使用的消息模板<small>可使用 {orderId}、{companyName}、{taxNo}、{invoiceType}、{email} 变量</small><textarea name="sellerMessageTemplate" rows="5">${esc(c.sellerMessageTemplate||'')}</textarea></label><div class="actions"><button type="submit" class="primary">保存开票资料</button></div></form>`);document.querySelector('#invoice-profile').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));try{await api('config','PUT',data);message('开票资料已保存到本机')}catch(error){message('保存失败：'+error.message)}}}catch(error){shell(`<div class="empty">无法读取开票资料：${esc(error.message)}</div>`)} }
function proofreadData(e,value){
 const tokens=value.trim()?value.trim().split(/[\s,，;；、]+/).filter(Boolean):[],parsed=tokens.map(text=>{const normalized=text.replace(/^[¥￥]\s*/,'').replace(/,/g,''),match=/^(\d+)(?:\.(\d{1,2}))?$/.exec(normalized);if(!match)return {text,cents:null};const cents=Number(match[1])*100+Number((match[2]||'').padEnd(2,'0'));return {text,cents:Number.isSafeInteger(cents)?cents:null}}),issued=(e.orders||[]).filter(order=>order.submission==='yes'&&statusTags(order).includes('已开票')),available=new Map();
 for(const order of issued){const match=/^(\d+)(?:\.(\d{1,2}))?$/.exec(String(order.amount||'').trim().replace(/^[¥￥]\s*/,'').replace(/,/g,''));if(!match)continue;const cents=Number(match[1])*100+Number((match[2]||'').padEnd(2,'0'));if(!Number.isSafeInteger(cents))continue;if(!available.has(cents))available.set(cents,[]);available.get(cents).push(order)}
 const unmatched=[];let matched=0;for(const item of parsed){if(item.cents===null){unmatched.push(item.text);continue}const list=available.get(item.cents)||[];if(list.shift())matched++;else unmatched.push(item.text)}
 const counts=new Map();for(const item of parsed)if(item.cents!==null)counts.set(item.cents,(counts.get(item.cents)||0)+1);const missing=[];for(const order of issued){const match=/^(\d+)(?:\.(\d{1,2}))?$/.exec(String(order.amount||'').trim().replace(/^[¥￥]\s*/,'').replace(/,/g,''));const cents=match?Number(match[1])*100+Number((match[2]||'').padEnd(2,'0')):null,remaining=cents===null?0:(counts.get(cents)||0);if(cents!==null&&remaining>0)counts.set(cents,remaining-1);else missing.push(order)}
 return {tokens,matched,unmatched,missing,invalid:parsed.filter(item=>item.cents===null).map(item=>item.text)};
}

