 shell(`<button class="link back" id="back">← 返回 Event 列表</button><div class="eyebrow">ORDER WORKSPACE</div><div class="title-row"><div><h1>${esc(e.name)}</h1><p>购买日期：${esc(rangeLabel(e))}</p></div><div><button id="edit-event">编辑 Event</button> <button id="refresh">检查开票进度</button> <button id="manual-add">手动添加订单</button> <button class="primary" id="scan">＋ 扫描订单</button></div></div><div class="notice">扫描会检查订单发票状态并尝试下载 PDF；已保存 PDF 的订单跳过检查。发现商家客服申请卡片时，扫描会尝试填写并提交；不会发送客服消息。</div><div class="stats"><div><small>订单总数</small><strong>${totals.total}</strong></div><div><small>已开票</small><strong>${totals.issued}</strong><small>其中 ${totals.savedPdf} 笔已保存 PDF</small></div><div><small>开票中</small><strong>${totals.systemPending+totals.sellerPending}</strong><div class="pending-counts"><small>系统开票：${totals.systemPending}</small><small>客服开票：${totals.sellerPending}</small></div></div><div><small>待确认</small><strong>${totals.review}</strong></div><div><small>已导出订单</small><strong>${totals.submitted}</strong></div><div><small>预计开票总金额</small><strong>${formatCents(amounts.expectedCents)}</strong>${amounts.missingExpected?`<small>${amounts.missingExpected} 笔订单金额未知，未计入</small>`:''}</div><div><small>已开票总金额</small><strong>${formatCents(amounts.issuedCents)}</strong>${amounts.missingIssued?`<small>${amounts.missingIssued} 笔订单金额未知，未计入</small>`:''}</div></div><p class="stats-note">金额按订单金额合计；状态按标签统计，每笔订单只计入一个类别。</p>${amountBreakdown(orders,amounts)}<section class="panel"><div class="panel-head orders-sticky-head"><div><h2>订单记录</h2><p>${latest?`最近扫描 ${esc(EventDates.formatRange(latest))} · 覆盖完整性未知，需人工校对订单数量。需要时手动录入`:'尚未扫描订单'}</p></div><div class="order-actions"><button id="proofread">校对</button><button id="edit-orders">编辑订单</button><button id="export-mode">导出</button> <div class="order-search"><div class="status-color-filters" role="group" aria-label="按状态颜色筛选"><button type="button" data-color-filter="待确认" aria-label="红色：待确认" aria-pressed="false"></button><button type="button" data-color-filter="手动录入" aria-label="紫色：手动录入" aria-pressed="false"></button><button type="button" data-color-filter="客服开票中" aria-label="蓝色：客服开票中" aria-pressed="false"></button><button type="button" data-color-filter="系统开票中" aria-label="黄色：系统开票中" aria-pressed="false"></button><button type="button" data-color-filter="已开票" aria-label="绿色：已开票" aria-pressed="false"></button></div><input id="search" placeholder="搜索店铺、订单号或金额"><small id="search-feedback" aria-live="polite"></small></div></div></div><div class="table-wrap orders-table"><table><thead><tr><th>序号</th><th>购买日期</th><th>店铺 / 订单</th><th>金额</th><th>状态 / 备注</th><th>是否导出</th><th>导出时间</th><th></th></tr></thead><tbody>${rows}</tbody></table>${rows?'':'<div class="empty">暂无订单。选择购买日期范围开始扫描。</div>'}</div></section>`);
 document.querySelector('#back').onclick=()=>{page='events';render()};document.querySelector('#edit-event').onclick=()=>eventForm(e.id);document.querySelector('#scan').onclick=scan;document.querySelector('#manual-add').onclick=()=>addManualOrder(e);document.querySelector('#export-mode').onclick=()=>enableExportSelection(e);document.querySelector('#refresh').onclick=()=>refreshInvoices();document.querySelector('#proofread').onclick=()=>proofreadExportedOrders(e);document.querySelector('#edit-orders').onclick=()=>editOrders(e);
 const search=document.querySelector('#search'),feedback=document.querySelector('#search-feedback'),proofreadButton=document.querySelector('#proofread');let proofreadMode=false,colorFilter='';
 const updateSearch=()=>{const raw=search.value.trim(),tableRows=[...document.querySelectorAll('tbody tr')];if(proofreadMode){if(!raw){feedback.textContent='输入数量：0；匹配且已开票：0；未匹配金额：无';for(const row of tableRows)row.hidden=false;return}const result=proofreadData(e,raw),missingIds=new Set(result.missing.map(order=>order.id));for(const row of tableRows)row.hidden=!missingIds.has(row.dataset.orderId);const unmatched=result.unmatched.length?result.unmatched.join('、'):'无';feedback.textContent=`输入数量：${result.tokens.length}；匹配且已开票：${result.matched}；未匹配金额：${unmatched}${result.invalid.length?`\n无法识别：${result.invalid.join('、')}`:''}`;return}const tokens=raw.toLowerCase().replace(/[¥￥]/g,'').split(/[,，;；\s]+/).filter(Boolean),isAmountToken=token=>/^\d{1,10}(?:\.\d{1,2})?$/.test(token.replace(/[¥￥,]/g,'')),amountTokens=tokens.length&&tokens.every(isAmountToken)?tokens:[],amountOf=row=>{const n=Number((row.dataset.orderAmount||'').replace(/[¥￥,\s]/g,''));return Number.isFinite(n)?n:null},matches=(row,token)=>amountOf(row)===Number(token.replace(/[¥￥,\s]/g,''));for(const row of tableRows){const text=row.textContent.toLowerCase(),colorMatch=!colorFilter||[...row.querySelectorAll('[data-field="status"] .status')].some(tag=>tag.textContent.trim()===colorFilter);row.hidden=!colorMatch||Boolean(raw)&&!(amountTokens.length?amountTokens.some(token=>matches(row,token)):text.includes(raw))}const matchedOrders=amountTokens.length?tableRows.filter(row=>amountTokens.some(token=>matches(row,token))):[],missingAmounts=[...new Set(amountTokens.filter(token=>!tableRows.some(row=>matches(row,token))))];feedback.textContent=amountTokens.length?`输入 ${amountTokens.length} 个金额，找到 ${matchedOrders.length} 笔订单${missingAmounts.length?`；未找到金额：${missingAmounts.map(value=>'¥ '+value).join('、')}`:''}`:''};
