async function uploadOrderImage(eventId,orderId,file){
 if(file.size>20*1024*1024)throw Error('图片不能超过 20 MB');
 const mime=file.type==='image/jpeg'||/\.jpe?g$/i.test(file.name)?'image/jpeg':'image/png';
 const r=await fetch(`/api/images/${encodeURIComponent(eventId)}/${encodeURIComponent(orderId)}`,{method:'POST',headers:{'Content-Type':mime,'X-Invoice-Request':'local-app'},body:file});const value=await r.json();if(!r.ok)throw Error(value.error||'图片上传失败');return value;
}
async function uploadOrderPdf(eventId,orderId,file){
 if(file.size>20*1024*1024)throw Error('PDF 不能超过 20 MB');
 const r=await fetch(`/api/invoices/${encodeURIComponent(eventId)}/${encodeURIComponent(orderId)}`,{method:'POST',headers:{'Content-Type':'application/pdf','X-Invoice-Request':'local-app'},body:file});const value=await r.json();if(!r.ok)throw Error(value.error||'PDF 上传失败');return value;
}
