  const selectedOrders=e.orders.filter(order=>ids.includes(order.id)),previous=selectedOrders.map(order=>({submission:order.submission,exportedAt:order.exportedAt})),exportedAt=new Date().toISOString();for(const order of selectedOrders){order.submission='yes';order.exportedAt=exportedAt}try{await save()}catch(err){selectedOrders.forEach((order,index)=>{order.submission=previous[index].submission;if(previous[index].exportedAt===undefined)delete order.exportedAt;else order.exportedAt=previous[index].exportedAt});throw Error(`压缩包已生成，但“是否导出”保存失败：${err.message}`)}render();message(`已导出 ${ids.length} 笔订单的发票，并勾选“是否导出”`)
